# ! [doc = " Inplace iterate-and-collect specialization for `Vec`"] # ! [doc = ""] # ! [doc = " Note: This documents Vec internals, some of the following sections explain implementation"] # ! [doc = " details and are best read together with the source of this module."] # ! [doc = ""] # ! [doc = " The specialization in this module applies to iterators in the shape of"] # ! [doc = " `source.adapter().adapter().adapter().collect::<Vec<U>>()`"] # ! [doc = " where `source` is an owning iterator obtained from [`Vec<T>`], [`Box<[T]>`][box] (by conversion to `Vec`)"] # ! [doc = " or [`BinaryHeap<T>`], the adapters guarantee to consume enough items per step to make room"] # ! [doc = " for the results (represented by [`InPlaceIterable`]), provide transitive access to `source`"] # ! [doc = " (via [`SourceIter`]) and thus the underlying allocation."] # ! [doc = " And finally there are alignment and size constraints to consider, this is currently ensured via"] # ! [doc = " const eval instead of trait bounds in the specialized [`SpecFromIter`] implementation."] # ! [doc = ""] # ! [doc = " [`BinaryHeap<T>`]: crate::collections::BinaryHeap"] # ! [doc = " [box]: crate::boxed::Box"] # ! [doc = ""] # ! [doc = " By extension some other collections which use `collect::<Vec<_>>()` internally in their"] # ! [doc = " `FromIterator` implementation benefit from this too."] # ! [doc = ""] # ! [doc = " Access to the underlying source goes through a further layer of indirection via the private"] # ! [doc = " trait [`AsVecIntoIter`] to hide the implementation detail that other collections may use"] # ! [doc = " `vec::IntoIter` internally."] # ! [doc = ""] # ! [doc = " In-place iteration depends on the interaction of several unsafe traits, implementation"] # ! [doc = " details of multiple parts in the iterator pipeline and often requires holistic reasoning"] # ! [doc = " across multiple structs since iterators are executed cooperatively rather than having"] # ! [doc = " a central evaluator/visitor struct executing all iterator components."] # ! [doc = ""] # ! [doc = " # Reading from and writing to the same allocation"] # ! [doc = ""] # ! [doc = " By its nature collecting in place means that the reader and writer side of the iterator"] # ! [doc = " use the same allocation. Since `try_fold()` (used in [`SpecInPlaceCollect`]) takes a"] # ! [doc = " reference to the iterator for the duration of the iteration that means we can't interleave"] # ! [doc = " the step of reading a value and getting a reference to write to. Instead raw pointers must be"] # ! [doc = " used on the reader and writer side."] # ! [doc = ""] # ! [doc = " That writes never clobber a yet-to-be-read items is ensured by the [`InPlaceIterable`] requirements."] # ! [doc = ""] # ! [doc = " # Layout constraints"] # ! [doc = ""] # ! [doc = " When recycling an allocation between different types we must uphold the [`Allocator`] contract"] # ! [doc = " which means that the input and output Layouts have to \"fit\"."] # ! [doc = ""] # ! [doc = " To complicate things further `InPlaceIterable` supports splitting or merging items into smaller/"] # ! [doc = " larger ones to enable (de)aggregation of arrays."] # ! [doc = ""] # ! [doc = " Ultimately each step of the iterator must free up enough *bytes* in the source to make room"] # ! [doc = " for the next output item."] # ! [doc = " If `T` and `U` have the same size no fixup is needed."] # ! [doc = " If `T`'s size is a multiple of `U`'s we can compensate by multiplying the capacity accordingly."] # ! [doc = " Otherwise the input capacity (and thus layout) in bytes may not be representable by the output"] # ! [doc = " `Vec<U>`. In that case `alloc.shrink()` is used to update the allocation's layout."] # ! [doc = ""] # ! [doc = " Alignments of `T` must be the same or larger than `U`. Since alignments are always a power"] # ! [doc = " of two _larger_ implies _is a multiple of_."] # ! [doc = ""] # ! [doc = " See `in_place_collectible()` for the current conditions."] # ! [doc = ""] # ! [doc = " Additionally this specialization doesn't make sense for ZSTs as there is no reallocation to"] # ! [doc = " avoid and it would make pointer arithmetic more difficult."] # ! [doc = ""] # ! [doc = " [`Allocator`]: core::alloc::Allocator"] # ! [doc = ""] # ! [doc = " # Drop- and panic-safety"] # ! [doc = ""] # ! [doc = " Iteration can panic, requiring dropping the already written parts but also the remainder of"] # ! [doc = " the source. Iteration can also leave some source items unconsumed which must be dropped."] # ! [doc = " All those drops in turn can panic which then must either leak the allocation or abort to avoid"] # ! [doc = " double-drops."] # ! [doc = ""] # ! [doc = " This is handled by the [`InPlaceDrop`] guard for sink items (`U`) and by"] # ! [doc = " [`vec::IntoIter::forget_allocation_drop_remaining()`] for remaining source items (`T`)."] # ! [doc = ""] # ! [doc = " If dropping any remaining source item (`T`) panics then [`InPlaceDstDataSrcBufDrop`] will handle dropping"] # ! [doc = " the already collected sink items (`U`) and freeing the allocation."] # ! [doc = ""] # ! [doc = " [`vec::IntoIter::forget_allocation_drop_remaining()`]: super::IntoIter::forget_allocation_drop_remaining()"] # ! [doc = ""] # ! [doc = " # O(1) collect"] # ! [doc = ""] # ! [doc = " The main iteration itself is further specialized when the iterator implements"] # ! [doc = " [`TrustedRandomAccessNoCoerce`] to let the optimizer see that it is a counted loop with a single"] # ! [doc = " [induction variable]. This can turn some iterators into a noop, i.e. it reduces them from O(n) to"] # ! [doc = " O(1). This particular optimization is quite fickle and doesn't always work, see [#79308]"] # ! [doc = ""] # ! [doc = " [#79308]: https://github.com/rust-lang/rust/issues/79308"] # ! [doc = " [induction variable]: https://en.wikipedia.org/wiki/Induction_variable"] # ! [doc = ""] # ! [doc = " Since unchecked accesses through that trait do not advance the read pointer of `IntoIter`"] # ! [doc = " this would interact unsoundly with the requirements about dropping the tail described above."] # ! [doc = " But since the normal `Drop` implementation of `IntoIter` would suffer from the same problem it"] # ! [doc = " is only correct for `TrustedRandomAccessNoCoerce` to be implemented when the items don't"] # ! [doc = " have a destructor. Thus that implicit requirement also makes the specialization safe to use for"] # ! [doc = " in-place collection."] # ! [doc = " Note that this safety concern is about the correctness of `impl Drop for IntoIter`,"] # ! [doc = " not the guarantees of `InPlaceIterable`."] # ! [doc = ""] # ! [doc = " # Adapter implementations"] # ! [doc = ""] # ! [doc = " The invariants for adapters are documented in [`SourceIter`] and [`InPlaceIterable`], but"] # ! [doc = " getting them right can be rather subtle for multiple, sometimes non-local reasons."] # ! [doc = " For example `InPlaceIterable` would be valid to implement for [`Peekable`], except"] # ! [doc = " that it is stateful, cloneable and `IntoIter`'s clone implementation shortens the underlying"] # ! [doc = " allocation which means if the iterator has been peeked and then gets cloned there no longer is"] # ! [doc = " enough room, thus breaking an invariant ([#85322])."] # ! [doc = ""] # ! [doc = " [#85322]: https://github.com/rust-lang/rust/issues/85322"] # ! [doc = " [`Peekable`]: core::iter::Peekable"] # ! [doc = ""] # ! [doc = ""] # ! [doc = " # Examples"] # ! [doc = ""] # ! [doc = " Some cases that are optimized by this specialization, more can be found in the `Vec`"] # ! [doc = " benchmarks:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " # #[allow(dead_code)]"] # ! [doc = " /// Converts a usize vec into an isize one."] # ! [doc = " pub fn cast(vec: Vec<usize>) -> Vec<isize> {"] # ! [doc = "   // Does not allocate, free or panic. On optlevel>=2 it does not loop."] # ! [doc = "   // Of course this particular case could and should be written with `into_raw_parts` and"] # ! [doc = "   // `from_raw_parts` instead."] # ! [doc = "   vec.into_iter().map(|u| u as isize).collect()"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " # #[allow(dead_code)]"] # ! [doc = " /// Drops remaining items in `src` and if the layouts of `T` and `U` match it"] # ! [doc = " /// returns an empty Vec backed by the original allocation. Otherwise it returns a new"] # ! [doc = " /// empty vec."] # ! [doc = " pub fn recycle_allocation<T, U>(src: Vec<T>) -> Vec<U> {"] # ! [doc = "   src.into_iter().filter_map(|_| None).collect()"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " let vec = vec![13usize; 1024];"] # ! [doc = " let _ = vec.into_iter()"] # ! [doc = "   .enumerate()"] # ! [doc = "   .filter_map(|(idx, val)| if idx % 2 == 0 { Some(val+idx) } else {None})"] # ! [doc = "   .collect::<Vec<_>>();"] # ! [doc = ""] # ! [doc = " // is equivalent to the following, but doesn't require bounds checks"] # ! [doc = ""] # ! [doc = " let mut vec = vec![13usize; 1024];"] # ! [doc = " let mut write_idx = 0;"] # ! [doc = " for idx in 0..vec.len() {"] # ! [doc = "    if idx % 2 == 0 {"] # ! [doc = "       vec[write_idx] = vec[idx] + idx;"] # ! [doc = "       write_idx += 1;"] # ! [doc = "    }"] # ! [doc = " }"] # ! [doc = " vec.truncate(write_idx);"] # ! [doc = " ```"] use split_decls_genesis :: ourprelude :: * ; use core :: alloc :: { Allocator , Layout } ; use core :: iter :: { InPlaceIterable , SourceIter , TrustedRandomAccessNoCoerce } ; use core :: marker :: PhantomData ; use core :: mem :: { self , ManuallyDrop , SizedTypeProperties } ; use core :: num :: NonZero ; use core :: ptr ; use super :: { InPlaceDrop , InPlaceDstDataSrcBufDrop , SpecFromIter , SpecFromIterNested , Vec } ; use crate :: alloc :: { Global , handle_alloc_error } ; const fn in_place_collectible < DEST , SRC > (step_merge : Option < NonZero < usize > > , step_expand : Option < NonZero < usize > > ,) -> bool { if const { SRC :: IS_ZST || DEST :: IS_ZST || align_of :: < SRC > () != align_of :: < DEST > () } { return false ; } match (step_merge , step_expand) { (Some (step_merge) , Some (step_expand)) => { size_of :: < SRC > () * step_merge . get () >= size_of :: < DEST > () * step_expand . get () } _ => false , } } const fn needs_realloc < SRC , DEST > (src_cap : usize , dst_cap : usize) -> bool { if const { align_of :: < SRC > () != align_of :: < DEST > () } { panic ! ("in_place_collectible() prevents this") ; } if const { let src_sz = size_of :: < SRC > () ; let dest_sz = size_of :: < DEST > () ; dest_sz != 0 && src_sz % dest_sz == 0 } { return false ; } src_cap > 0 && src_cap * size_of :: < SRC > () != dst_cap * size_of :: < DEST > () } #[doc = " This provides a shorthand for the source type since local type aliases aren't a thing."] #[rustc_specialization_trait] trait InPlaceCollect : SourceIter < Source : AsVecIntoIter > + InPlaceIterable { type Src ; } impl < T > InPlaceCollect for T where T : SourceIter < Source : AsVecIntoIter > + InPlaceIterable , { type Src = < < T as SourceIter > :: Source as AsVecIntoIter > :: Item ; } impl < T , I > SpecFromIter < T , I > for Vec < T > where I : Iterator < Item = T > + InPlaceCollect , < I as SourceIter > :: Source : AsVecIntoIter , { #[track_caller] default fn from_iter (iterator : I) -> Self { let fun : fn (I) -> Vec < T > = const { if in_place_collectible :: < T , I :: Src > (I :: MERGE_BY , I :: EXPAND_BY) { from_iter_in_place } else { SpecFromIterNested :: < T , I > :: from_iter } } ; fun (iterator) } } #[track_caller] fn from_iter_in_place < I , T > (mut iterator : I) -> Vec < T > where I : Iterator < Item = T > + InPlaceCollect , < I as SourceIter > :: Source : AsVecIntoIter , { let (src_buf , src_ptr , src_cap , mut dst_buf , dst_end , dst_cap) = unsafe { let inner = iterator . as_inner () . as_into_iter () ; (inner . buf , inner . ptr , inner . cap , inner . buf . cast :: < T > () , inner . end as * const T , inner . cap . unchecked_mul (size_of :: < I :: Src > ()) / size_of :: < T > () ,) } ; let len = unsafe { SpecInPlaceCollect :: collect_in_place (& mut iterator , dst_buf . as_ptr () as * mut T , dst_end) } ; let src = unsafe { iterator . as_inner () . as_into_iter () } ; debug_assert_eq ! (src_buf , src . buf) ; if src . ptr != src_ptr { debug_assert ! (unsafe { dst_buf . add (len) . cast () } <= src . ptr , "InPlaceIterable contract violation, write pointer advanced beyond read pointer") ; } let dst_guard = InPlaceDstDataSrcBufDrop { ptr : dst_buf , len , src_cap , src : PhantomData :: < I :: Src > } ; src . forget_allocation_drop_remaining () ; if needs_realloc :: < I :: Src , T > (src_cap , dst_cap) { let alloc = Global ; debug_assert_ne ! (src_cap , 0) ; debug_assert_ne ! (dst_cap , 0) ; unsafe { let src_align = align_of :: < I :: Src > () ; let src_size = size_of :: < I :: Src > () . unchecked_mul (src_cap) ; let old_layout = Layout :: from_size_align_unchecked (src_size , src_align) ; let dst_align = align_of :: < T > () ; let dst_size = size_of :: < T > () . unchecked_mul (dst_cap) ; let new_layout = Layout :: from_size_align_unchecked (dst_size , dst_align) ; let result = alloc . shrink (dst_buf . cast () , old_layout , new_layout) ; let Ok (reallocated) = result else { handle_alloc_error (new_layout) } ; dst_buf = reallocated . cast :: < T > () ; } } else { debug_assert_eq ! (src_cap * size_of ::< I :: Src > () , dst_cap * size_of ::< T > ()) ; } mem :: forget (dst_guard) ; let vec = unsafe { Vec :: from_parts (dst_buf , len , dst_cap) } ; vec } fn write_in_place_with_drop < T > (src_end : * const T ,) -> impl FnMut (InPlaceDrop < T > , T) -> Result < InPlaceDrop < T > , ! > { move | mut sink , item | { unsafe { debug_assert ! (sink . dst as * const _ <= src_end , "InPlaceIterable contract violation") ; ptr :: write (sink . dst , item) ; sink . dst = sink . dst . add (1) ; } Ok (sink) } } #[doc = " Helper trait to hold specialized implementations of the in-place iterate-collect loop"] trait SpecInPlaceCollect < T , I > : Iterator < Item = T > { #[doc = " Collects an iterator (`self`) into the destination buffer (`dst`) and returns the number of items"] #[doc = " collected. `end` is the last writable element of the allocation and used for bounds checks."] #[doc = ""] #[doc = " This method is specialized and one of its implementations makes use of"] #[doc = " `Iterator::__iterator_get_unchecked` calls with a `TrustedRandomAccessNoCoerce` bound"] #[doc = " on `I` which means the caller of this method must take the safety conditions"] #[doc = " of that trait into consideration."] unsafe fn collect_in_place (& mut self , dst : * mut T , end : * const T) -> usize ; } impl < T , I > SpecInPlaceCollect < T , I > for I where I : Iterator < Item = T > , { #[inline] default unsafe fn collect_in_place (& mut self , dst_buf : * mut T , end : * const T) -> usize { let sink = InPlaceDrop { inner : dst_buf , dst : dst_buf } ; let sink = self . try_fold :: < _ , _ , Result < _ , ! > > (sink , write_in_place_with_drop (end)) . into_ok () ; unsafe { ManuallyDrop :: new (sink) . dst . offset_from_unsigned (dst_buf) } } } impl < T , I > SpecInPlaceCollect < T , I > for I where I : Iterator < Item = T > + TrustedRandomAccessNoCoerce , { #[inline] unsafe fn collect_in_place (& mut self , dst_buf : * mut T , end : * const T) -> usize { let len = self . size () ; let mut drop_guard = InPlaceDrop { inner : dst_buf , dst : dst_buf } ; for i in 0 .. len { unsafe { let dst = dst_buf . add (i) ; debug_assert ! (dst as * const _ <= end , "InPlaceIterable contract violation") ; ptr :: write (dst , self . __iterator_get_unchecked (i)) ; drop_guard . dst = dst . add (1) ; } } mem :: forget (drop_guard) ; len } } #[doc = " Internal helper trait for in-place iteration specialization."] #[doc = ""] #[doc = " Currently this is only implemented by [`vec::IntoIter`] - returning a reference to itself - and"] #[doc = " [`binary_heap::IntoIter`] which returns a reference to its inner representation."] #[doc = ""] #[doc = " Since this is an internal trait it hides the implementation detail `binary_heap::IntoIter`"] #[doc = " uses `vec::IntoIter` internally."] #[doc = ""] #[doc = " [`vec::IntoIter`]: super::IntoIter"] #[doc = " [`binary_heap::IntoIter`]: crate::collections::binary_heap::IntoIter"] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " In-place iteration relies on implementation details of `vec::IntoIter`, most importantly that"] #[doc = " it does not create references to the whole allocation during iteration, only raw pointers"] #[rustc_specialization_trait] pub (crate) unsafe trait AsVecIntoIter { type Item ; fn as_into_iter (& mut self) -> & mut super :: IntoIter < Self :: Item > ; }